BEGIN;
CREATE TABLE IF NOT EXISTS saas_merchant (id SERIAL PRIMARY KEY, slug VARCHAR(64) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, password_hash VARCHAR(256) NOT NULL, address VARCHAR(300), registration_ref VARCHAR(100), status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS saas_bill (id SERIAL PRIMARY KEY, merchant_id INTEGER NOT NULL REFERENCES saas_merchant(id), token VARCHAR(64) UNIQUE NOT NULL, customer VARCHAR(120) NOT NULL, description VARCHAR(300) NOT NULL, total NUMERIC(12,2) NOT NULL, brand VARCHAR(120) NOT NULL, address VARCHAR(300));
CREATE INDEX IF NOT EXISTS ix_saas_bill_merchant_id ON saas_bill(merchant_id);
COMMIT;
